class TestCheckPrescriptiveKills:
    def test_all_pass(self):
        expected = {"VALUE": True, "SWAP": True}
        per_cat = [
            {"category": "VALUE", "survived": 0},
            {"category": "SWAP", "survived": 0},
        ]
        result = _check_prescriptive_kills(expected, per_cat)
        assert result == {"VALUE": "pass", "SWAP": "pass"}

    def test_fail_on_survival(self):
        expected = {"VALUE": True}
        per_cat = [{"category": "VALUE", "survived": 3}]
        result = _check_prescriptive_kills(expected, per_cat)
        assert result["VALUE"] == "fail"

    def test_unknown_when_missing(self):
        expected = {"BOUNDARY": True}
        per_cat = [{"category": "VALUE", "survived": 0}]
        result = _check_prescriptive_kills(expected, per_cat)
        assert result["BOUNDARY"] == "unknown"

    def test_empty_expectations(self):
        assert _check_prescriptive_kills({}, []) == {}


class TestUpdateStagedArtifacts:
    def test_reference_only(self):
        artifacts: list[dict] = []
        gen_result = {
            "skipped_reason": "existing_tests_adequate",
            "generated_path": "tests/gen/test_a.py",
            "canonical_path": "tests/test_a.py",
        }
        _update_staged_artifacts(artifacts, gen_result, 1)
        assert len(artifacts) == 1
        assert artifacts[0]["reference_only"] is True

    def test_new_staged_artifact(self):
        artifacts: list[dict] = []
        gen_result = {
            "files_written": 1,
            "staging_path": "/tmp/staged/test_a.py",
            "generated_path": "tests/generated/test_a.py",
            "content_hash": "abc123",
        }
        _update_staged_artifacts(artifacts, gen_result, 2)
        assert len(artifacts) == 1
        assert artifacts[0]["source_iteration"] == 2

    def test_updates_existing(self):
        artifacts = [{"generated_path": "tests/generated/test_a.py", "content_hash": "old"}]
        gen_result = {
            "files_written": 1,
            "staging_path": "/tmp/staged/test_a.py",
            "generated_path": "tests/generated/test_a.py",
            "content_hash": "new",
        }
        _update_staged_artifacts(artifacts, gen_result, 3)
        assert len(artifacts) == 1
        assert artifacts[0]["content_hash"] == "new"

    def test_no_op_on_empty_result(self):
        artifacts: list[dict] = []
        _update_staged_artifacts(artifacts, {}, 1)
        assert artifacts == []


